{"hypotheses": [
  {
    "name": "Intangible Value-Momentum Synergy",
    "mechanism": "Firms with high intangible assets (IntanBM) often face valuation uncertainty, but when combined with momentum (Mom12m), positive price trends may indicate market recognition of intangible value. This composite exploits periods when both value (intangible BM) and momentum signals align, capturing returns missed by using either alone.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "IntanBM"},
        {"weight": 0.5, "primitive": "Mom12m"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Low Leverage, High Profitability in Volatile Markets",
    "mechanism": "Leveraging the tendency for low-leverage (Leverage) and highly profitable (OperProf) firms to outperform during high-volatility periods, this composite captures risk-off rotation into quality stocks when VIX is elevated.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "Leverage"},
        {"weight": 1.0, "primitive": "OperProf"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Cash-Efficient Growth in Low Rate Environments",
    "mechanism": "This composite benefits from the synergy between asset growth (AssetGrowth) and cash productivity (CashProd), but only when the term spread is positive—indicating a normal yield curve and supportive credit conditions for growth firms that are also efficient in cash usage.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": 0.5, "primitive": "CashProd"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Momentum with Analyst Disagreement",
    "mechanism": "Firms with strong earnings surprise (EarningsSurprise) but high analyst forecast dispersion (ForecastDispersion) indicate situations where the market is slow to fully incorporate positive information, enabling further drift in price.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Liquidity Value with Sentiment Overhang",
    "mechanism": "Combining book-to-market (BM) with the negative of Amihud’s illiquidity (Illiquidity) captures the premium from neglected value stocks that are also less liquid, especially potent in periods when VIX is low and risk aversion is muted.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 40
  },
  {
    "name": "Short-Term Reversal in Junk Momentum",
    "mechanism": "Negative momentum in 'junk' stocks (Mom6mJunk), when paired with short-term reversal (STreversal), exploits the tendency for the most beaten-down low-quality stocks to mean-revert, especially after sharp declines.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom6mJunk"},
        {"weight": 1.0, "primitive": "STreversal"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Organizational Capital and Repurchases",
    "mechanism": "Firms with high organizational capital (OrgCap) that are also actively repurchasing shares (ShareRepurchase) may signal both internal quality and external shareholder alignment, resulting in persistent future returns as both attributes reinforce each other.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": 0.5, "primitive": "ShareRepurchase"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "R&D Efficiency and Capital Discipline",
    "mechanism": "Firms with high R&D-to-market cap (RD) and low net equity financing (NetEquityFinance) combine innovative investment with prudent capital management, capturing the premium for disciplined growth. The edge is greatest in positive term spread regimes, which support external funding.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "RD"},
        {"weight": -0.5, "primitive": "NetEquityFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "RD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 30
  }
]}
